WITH lines AS (SELECT base.id, base.customer_id, base.created_at, base.coupon_codes, line.promo FROM carts base LATERAL VIEW EXPLODE(base.items) x AS line), lines_carts AS (SELECT id, customer_id, created_at, promo, EXPLODE(coupon_codes) AS tag FROM lines), valid AS (SELECT customer_id, created_at, tag, CASE WHEN tag = 'BUNDLE' THEN 1 ELSE 0 END AS is_bundle, COALESCE(promo, 'UNKNOWN') AS resolved_promo FROM lines_carts WHERE created_at >= TO_DATE('2025-03-01')), joined AS (SELECT a.customer_id, a.is_bundle, c.credit_limit, c.segment, c.email FROM valid a LEFT JOIN customers c ON a.customer_id = c.id), joined_carts AS (SELECT s.*, p.email AS customer_email FROM joined s LEFT JOIN customers p ON s.customer_id = p.id) SELECT s.customer_id, s.is_bundle, s.credit_limit, s.email, (SELECT AVG(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS avg_subscription_monthly_fee FROM joined_carts s ORDER BY credit_limit DESC;
